const $=s=>document.querySelector(s);
const paths={play:'m9 5 11 7-11 7Z',pause:'M8 5v14 M16 5v14',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8C2 8 6 0 10 5l2 3c10 0 6-8 2-3z',home:'m3 10 9-7 9 7 M5 9v12h5v-7h4v7h5V9',spark:'m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',trophy:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v6 M8 21h8 M9 19h6',ticket:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4z M15 6v3 M15 11v2 M15 15v3',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',logout:'M9 5H4v14h5 M12 12h9 m-4-4 4 4-4 4',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',heart:'M12 21S2 14 2 7a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 14-10 14z',camera:'M3 7h5l2-3h4l2 3h5v14H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',users:'M8 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M2 21v-5a6 6 0 0 1 12 0v5 M17 3a3 3 0 0 1 0 6 M17 11a5 5 0 0 1 5 5v5',chart:'M4 3v18h18 M8 17v-5 M13 17V7 M18 17v-9',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6',code:'m8 7-5 5 5 5 m8-10 5 5-5 5 M14 4l-4 16',box:'m3 7 9-4 9 4v12l-9 3-9-3z M3 7l9 4 9-4 M12 11v11',balloons:'M9 3a5 6 0 1 0 0 12 5 6 0 0 0 0-12 M9 15v7 M17 5a4 5 0 0 1 0 10v7',truck:'M2 6h12v12H2z M14 10h4l4 5v3h-8 M6 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M18 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6',menu:'M4 6h16 M4 12h16 M4 18h16',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',download:'M12 3v12 m-4-4 4 4 4-4 M4 16v5h16v-5',copy:'M8 8h12v13H8z M16 8V3H3v13h5',leaf:'M20 3C5 3 1 13 7 18S22 14 20 3 M5 21l11-12'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.gift}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(v,time=false)=>new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',...(time?{timeStyle:'short'}:{}),timeZone:'America/Bogota'}).format(new Date(v));
const roleName=r=>({admin:'Administración',explorer:'Cliente explorador',ambassador:'Cliente embajador'}[r]);
const statusName=s=>({pending:'Pendiente',confirmed:'Confirmada',cancelled:'Cancelada',issued:'Disponible',used:'Utilizado',approved:'Aprobada',rejected:'Rechazada',expired:'Vencido'}[s]||s);
const status=s=>`<span class="status ${esc(s)}">${statusName(s)}</span>`;
const empty=(message,type='gift')=>`<div class="empty">${icon(type)}${message}</div>`;
const brand=()=>`<div class="brand"><img src="/favicon.svg" width="37" height="37" alt=""><div><div class="brand-name">milfiguras<span style="color:#b57b88">.</span></div><small>DETALLES QUE CONECTAN</small></div></div>`;
const scene=()=>`<div class="gift-scene" aria-hidden="true"><div class="halo"></div><div class="gift-box"></div><div class="bow"></div><div class="gift-tag">para ti ♡</div><div class="flower">✿</div><span class="spark s1">✧</span><span class="spark s2">✦</span><span class="spark s3">✧</span><div class="ribbon-label">hecho con amor ♡</div></div>`;
let state=null,page='home',tab='reservations',metricDays=7,includeDemo=false,metricData=null,register=false,busy=false;
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&state){state=null;renderAuth();}throw new Error(data.error||'No se pudo completar la solicitud.');}return data;}
let toastTimer;function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',6500);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<16;i++){const el=document.createElement('span');el.className='confetti';el.textContent=['✦','♡','✧'][i%3];el.style.color=['#b76b83','#caaa71','#a69abb'][i%3];el.style.setProperty('--dx',(Math.random()*500-250)+'px');el.style.setProperty('--dy',(Math.random()*260+80)+'px');document.body.append(el);setTimeout(()=>el.remove(),1400);}}
function modal(title,html){const d=$('#modal');d.classList.remove('video-dialog','configuration-dialog');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-action="close-modal" aria-label="Cerrar">×</button></div>${html}`;d.showModal();}
function closeModal(){$('#modal').close();}
function formError(form,error){const el=form.querySelector('.modal-error,.auth-error');if(el&&form.isConnected&&(!form.closest('dialog')||form.closest('dialog').open))el.textContent=error.message;else toast(error.message,true);}
async function refresh(){state=await api('state');if(state.user.role==='admin')metricData=await api(`metrics?days=${metricDays}&demo=${includeDemo}`);render();}
function renderAuth(){document.body.classList.remove('navigation-open');document.title='Milfiguras BGA · Detalles que conectan';$('#app').innerHTML=`${publicStorefront()}<section class="account-section" id="account"><div class="account-note"><span class="eyebrow">AQUÍ EMPIEZA TU PRÓXIMO DETALLE</span><h2>Un lugar para crear.<br>Mil motivos para volver.</h2><p>Guarda tus pedidos, consulta su estado y disfruta las recompensas de tu club.</p></div><div class="auth-form"><div class="auth-inner"><span class="eyebrow">BIENVENIDO A TU CLUB</span><h2>${register?'Tu próxima sorpresa empieza aquí.':'Qué bonito verte de nuevo.'}</h2><p>${register?'Crea tu cuenta y empieza a dar vida a tus detalles.':'Ingresa y descubre todo lo que puedes crear.'}</p><form id="auth-form">${register?'<div class="field"><label for="name">Tu nombre</label><input id="name" name="name" required minlength="2" maxlength="80" autocomplete="name" placeholder="¿Cómo te llamas?"></div>':''}<div class="field"><label for="email">Correo electrónico</label><input id="email" name="email" required type="email" maxlength="120" autocomplete="email" placeholder="tu@correo.com"></div><div class="field"><label for="password">Contraseña</label><input id="password" name="password" required type="password" minlength="10" maxlength="120" autocomplete="${register?'new-password':'current-password'}" placeholder="Mínimo 10 caracteres"></div>${register?'<div class="field"><label for="referralCode">Código de invitación <span class="muted">(opcional)</span></label><input id="referralCode" name="referralCode" maxlength="20" placeholder="Un detalle compartido"></div><label class="check"><input type="checkbox" name="consent" required><span>Acepto el tratamiento de mis datos para reservas y participación en el club. He leído la <button type="button" data-action="privacy" style="color:var(--rose);padding:0;text-decoration:underline">política de privacidad</button>. Puedo retirar mi consentimiento eliminando mi cuenta.</span></label>':''}<p class="auth-error" role="alert"></p><button class="btn full" type="submit">${register?'Crear mi cuenta':'Entrar al club'} ${icon('arrow')}</button></form><div class="auth-switch">${register?'¿Ya eres parte?':'¿Tu primera visita?'} <button data-action="auth-switch">${register?'Inicia sesión':'Crea tu cuenta'}</button></div><p class="small muted" style="margin-top:24px">El acceso de administración requiere una cuenta autorizada y su contraseña.</p><div class="small muted" style="text-align:center;margin-top:28px">Milfiguras BGA · <a href="https://www.instagram.com/milfiguras_bga/" target="_blank" rel="noopener noreferrer">@milfiguras_bga</a></div></div></div></section>`;activateShowcase();}
const clientNav=[['home','home','Mi espacio'],['create','gift','Arma tu sorpresa'],['challenges','spark','Retos del club'],['rewards','ticket','Recompensas'],['progress','trophy','Mi progreso'],['orders','box','Mis reservas'],['coupons','heart','Mis cupones']];
const adminNav=[['home','chart','Resumen'],['manage','box','Operación'],['rewards','ticket','Recompensas'],['challenges','spark','Retos del club'],['users','users','Clientes'],['pilot','shield','Piloto y métricas']];
const names={home:'Mi espacio',create:'Arma tu sorpresa',challenges:'Retos del club',rewards:'Recompensas',progress:'Mi progreso',orders:'Mis reservas',coupons:'Mis cupones',manage:'Operación',users:'Clientes',pilot:'Piloto y métricas'};
function render(){if(!state){renderAuth();return;}const u=state.user,admin=u.role==='admin';if(admin&&!adminNav.some(n=>n[0]===page)||!admin&&!clientNav.some(n=>n[0]===page))page='home';document.title=`${admin&&page==='home'?'Resumen':names[page]} · Milfiguras BGA`;$('#app').innerHTML=`<div class="shell"><button type="button" class="navigation-backdrop" data-action="close-menu" aria-label="Cerrar menú de navegación" hidden></button><aside class="sidebar" id="main-navigation"><div class="sidebar-heading">${brand()}<button type="button" class="sidebar-close" data-action="close-menu" aria-label="Cerrar menú">×</button></div><div class="nav-label">${admin?'GESTIÓN DEL CLUB':'TU CLUB DE SORPRESAS'}</div><nav class="nav" aria-label="Navegación principal">${(admin?adminNav:clientNav).map(([id,ic,title])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${title}${id==='coupons'&&state.coupons.filter(c=>c.status==='issued'&&Date.parse(c.expiresAt)>Date.now()).length?`<span class="counter">${state.coupons.filter(c=>c.status==='issued'&&Date.parse(c.expiresAt)>Date.now()).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note">${icon('heart')}<strong class="small">Un detalle hace la diferencia</strong><p>${admin?'Cada acción del club, con propósito. Acompaña a tus clientes a crear momentos.':'Aquí no hay prisa. Los mejores momentos se preparan con cariño.'}</p></div><div class="sidebar-footer"><button type="button" class="sidebar-profile" data-action="edit-profile" aria-label="Modificar mi perfil">${avatarMarkup(u)}</button><div><strong>${esc(u.name.split(' ')[0])} ${u.role==='ambassador'?'✧':''}</strong><span class="tiny muted">${roleName(u.role)}</span></div><button class="logout" data-action="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb"><button type="button" class="mobile-menu" data-action="menu" aria-label="Abrir menú" aria-controls="main-navigation" aria-expanded="false">${icon('menu')}</button><span class="breadcrumb-parent">Club de Sorpresas</span>${icon('chevron')}<strong>${admin&&page==='home'?'Resumen':names[page]}</strong></div><div class="top-actions">${u.isDemo?'<span class="demo-tag">DEMOSTRACIÓN</span>':''}${admin?`<span class="small muted">${icon('shield')} Panel de gestión</span>`:`<span class="points-pill">${icon('star')} ${u.balance.toLocaleString('es-CO')} puntos</span>`}${profileControl(u)}</div></header><div class="content" id="page-content">${pageContent(admin)}</div><div class="workspace-footer"><footer class="footer-note"><span>© ${new Date().getFullYear()} Milfiguras BGA · Detalles que conectan.</span><span><button data-action="privacy" style="font-size:inherit;color:inherit;padding:0">Privacidad y condiciones</button> · <a href="https://www.instagram.com/milfiguras_bga/" target="_blank" rel="noopener noreferrer">Hablemos ♡</a></span></footer></div></main></div>`;activateShowcase();prepareResponsiveTables();setNavigationOpen(false);}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action||`<span class="date-label">${icon('calendar')}${date(new Date())}</span>`}</div>`;}
function stat(label,value,note,ic){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-bottom">${note}</div></div>`;}
function levelPanel(){const u=state.user;const next=state.levels.find(l=>l.min>u.xp);const progress=next?Math.min(100,u.xp/next.min*100):100;const badges=[['heart','Primer detalle',state.reservations.some(r=>r.status==='confirmed')],['clock','Con tiempo',state.ledger.some(l=>l.key.startsWith('reservation:'))],['star','Embajador',u.role==='ambassador']];return `<section class="panel level-panel"><div class="level-medallion">${icon('trophy')}</div><span class="eyebrow">TU NIVEL ACTUAL</span><h3>${esc(u.level.name)}</h3><p>${next?`${next.min-u.xp} XP para tu próximo nivel`:'Llegaste a Cliente VIP. ¡Gracias por estar aquí!'}</p><div class="progress" role="progressbar" aria-label="Progreso de nivel" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${progress}%"></span></div><div class="progress-label"><span>${u.xp} XP</span><span>${next?next.min+' XP':'VIP'}</span></div><div class="badges">${badges.map(([ic,t,earned])=>`<div class="badge ${earned?'earned':''}"><span>${icon(ic)}</span>${t}</div>`).join('')}</div></section>`;}
const challengeIcon={reservation:'gift',purchase:'code',trivia:'spark',photo:'camera'};
function challengesList(limit=99){return `<div class="challenge-list">${state.challenges.filter(c=>c.active).slice(0,limit).map(c=>`<article class="challenge-card"><div class="challenge-icon">${icon(challengeIcon[c.type])}</div><div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><span class="xp-tag">✦ +${c.points} XP</span></div><button class="action" data-challenge="${c.type}">Participar ${icon('chevron')}</button></article>`).join('')||empty('Pronto habrá nuevos retos para ti.','spark')}</div>`;}
function activity(){return `<section class="activity"><div class="section-title"><h2>Pequeños pasos, bonitas historias</h2><span class="tiny muted">TU ACTIVIDAD RECIENTE</span></div>${state.ledger.length?state.ledger.slice(0,5).map(l=>`<div class="activity-row">${icon(l.amount>0?'spark':'ticket')}<div>${esc(l.reason)}<small>${date(l.at,true)}</small></div><span class="activity-amount ${l.amount<0?'negative':''}">${l.amount>0?'+':''}${l.amount} XP</span></div>`).join(''):empty('Tu historia empieza con el primer reto. ¿Creamos algo bonito?','leaf')}</section>`;}
function home(){const u=state.user;const activeCoupons=state.coupons.filter(c=>c.status==='issued'&&Date.parse(c.expiresAt)>Date.now());const reward=state.rewards.find(r=>r.active&&r.stock>0);return `${heading(`Hola, ${u.name.split(' ')[0]} ♡`,'Hoy es un buen día para sorprender a alguien.')}${welcomeFeature('member')}<section class="stats" aria-label="Tu resumen">${stat('Tus puntos disponibles',`${u.balance}<small>pts</small>`,'Para tu próxima recompensa','star')}${stat('Experiencia acumulada',`${u.xp}<small>XP</small>`,esc(u.level.name),'trophy')}${stat('Sorpresas reservadas',state.reservations.length,`${state.reservations.filter(r=>r.status==='confirmed').length} confirmadas con cariño`,'gift')}${stat('Cupones por disfrutar',activeCoupons.length,'Pequeños beneficios, grandes sonrisas','ticket')}</section><div class="columns"><div><div class="section-title"><h2>Un reto, un nuevo motivo</h2><button data-page="challenges">Ver todos ${icon('arrow')}</button></div>${challengesList(3)}${activity()}</div><aside class="right-column">${levelPanel()}${reward?`<section class="panel"><h3 class="subtle-title">TU PRÓXIMA RECOMPENSA</h3><div class="mini-reward"><div class="reward-art">${icon('gift')}</div><div><h3>${esc(reward.title)}</h3><p>${reward.cost} puntos · ${reward.stock} disponibles</p><button class="btn ghost" data-page="rewards">Descubrir ${icon('arrow')}</button></div></div></section>`:''}</aside></div>`;}
function createPage(){return `${heading('Dale forma a tu próxima sorpresa','Elige el tamaño, los sabores y los detalles que la hacen única.')}<div class="notice">${icon('clock')} Reserva con al menos 48 horas de anticipación. El equipo confirma precio, disponibilidad y entrega contigo. Esta solicitud no genera un cobro.</div>${serviceOverview(true)}${extraServices(true)}`;}
function rewardsPage(admin){return `${heading(admin?'Beneficios que hacen volver':'Un pequeño premio para tu gran detalle',admin?'Configura costos, existencias y disponibilidad.':'Tus puntos se convierten en nuevas formas de sorprender.',admin?'<button class="btn" data-action="new-reward">+ Nueva recompensa</button>':'')}<div class="notice">Los puntos de experiencia definen tu nivel y no se pierden al canjear. Tu saldo disponible sí se descuenta. Los cupones duran 30 días, son de un solo uso y deben validarse con Milfiguras.</div><div class="grid-3">${state.rewards.filter(r=>admin||r.active).map(r=>`<article class="reward-card"><div class="reward-art">${icon(({topper:'gift',balloons:'balloons',discount:'ticket',shipping:'truck'})[r.kind]||'gift')}</div><div class="reward-body"><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="reward-meta"><span class="xp-tag">✦ ${r.cost} puntos</span><span class="tiny muted">${r.stock} disponibles${!r.active?' · Pausada':''}</span></div>${admin?`<button class="btn secondary full" data-edit-reward="${r.id}">Editar recompensa ${icon('settings')}</button>`:`<button class="btn ${state.user.balance<r.cost?'secondary':''} full" data-redeem="${r.id}" ${state.user.balance<r.cost||!r.stock?'disabled':''}>${!r.stock?'Agotada':state.user.balance<r.cost?`Te faltan ${r.cost-state.user.balance} puntos`:'Canjear recompensa'} ${icon('arrow')}</button>`}</div></article>`).join('')}</div>`;}
function challengesPage(admin){return `${heading(admin?'Cada acción tiene un propósito':'Más formas de hacer magia',admin?'Administra los retos y sus reglas de puntuación.':'Participa a tu ritmo. Lo importante es disfrutar el detalle.')}<div class="columns"><div>${admin?state.challenges.map(c=>`<article class="challenge-card" style="margin-bottom:15px"><div class="challenge-icon">${icon(challengeIcon[c.type])}</div><div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><span class="xp-tag">+${c.points} XP · ${c.active?'Activo':'Pausado'}</span></div><button class="action" data-edit-challenge="${c.id}">Editar ${icon('settings')}</button></article>`).join(''):challengesList()}</div><aside><section class="panel"><span class="eyebrow muted">UN CLUB CON PROPÓSITO</span><h2 style="margin-top:15px">Detalles que suman.</h2><p class="small muted">Premiamos la anticipación, las compras verificadas y la creatividad. Cada reto explica cómo participar y cuándo recibirás tus puntos.</p><p class="small muted">Sin compras obligatorias, premios al azar ni rachas que te penalicen. Una trivia por día y recompensas sujetas a existencias.</p></section>${!admin?`<section class="panel"><h3>Una sonrisa compartida</h3><p class="small muted">Invita a alguien con tu código. Si registra su primera compra verificada, recibes 60 XP.</p><code>${esc(state.user.referralCode)}</code><button class="btn ghost" data-copy="${state.user.referralCode}">${icon('copy')} Copiar código</button></section>`:''}</aside></div>`;}
function ordersTable(admin){return state.reservations.length?`<div class="table-scroll"><table class="reservations-table" aria-label="Reservas y detalles de los pedidos"><thead><tr><th>DETALLE</th>${admin?'<th>CLIENTE</th>':''}<th>ENTREGA · COLOMBIA</th><th>ESTADO</th><th>${admin?'GESTIÓN':'PUNTOS Y PEDIDO'}</th></tr></thead><tbody>${state.reservations.map(r=>`<tr><td><div class="reservation-reference">${esc(orderReference(r))}</div><strong>${esc(r.product)}</strong>${orderDetailsMarkup(r)}<small>${esc(r.occasion)} · Para ${esc(r.recipient)}</small><small>Color ${esc(r.color)} · «${esc(r.message)}»</small></td>${admin?`<td>${esc(r.customer)}<small>${esc(r.contactPhone||'Celular por confirmar')}</small></td>`:''}<td>${date(r.delivery,true)}<small>${r.deliveryMethod==='pickup'?'Recogida coordinada':esc(r.address||'Dirección por confirmar')}</small><small>Solicitada ${date(r.createdAt)}</small></td><td>${status(r.status)}</td><td>${admin&&r.status==='pending'?`<div class="inline-actions"><button type="button" class="btn" data-order="${r.id}" data-status="confirmed">Confirmar</button><button type="button" class="btn secondary" data-order="${r.id}" data-status="cancelled">Cancelar</button></div>`:`<span class="xp-tag">${r.status==='cancelled'?'Sin puntos':r.status==='confirmed'?'+'+r.points+' XP':'Al confirmar: +'+r.points+' XP'}</span>`}${admin&&r.contactPhone?`<div class="order-contact"><a href="https://wa.me/57${esc(r.contactPhone)}?text=${encodeURIComponent('Hola, te contactamos de Milfiguras BGA sobre tu pedido '+orderReference(r)+'. Su estado actual es: '+statusName(r.status)+'. Coordinemos los detalles de tu sorpresa.') }" target="_blank" rel="noopener noreferrer">Contactar cliente ↗</a></div>`:!admin&&r.status!=='cancelled'?`<button type="button" class="btn ghost" data-share-order="${esc(r.id)}">Ver resumen / WhatsApp ${icon('arrow')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay reservas. Los próximos momentos están por escribirse.','calendar');}
function couponsPage(){return `${heading('Momentos listos para disfrutar','Presenta tu código al equipo de Milfiguras al coordinar tu próximo pedido.')}<div class="notice">Cada código es de un solo uso, personal y válido durante 30 días. La recompensa queda confirmada cuando el equipo valida el cupón.</div>${state.coupons.length?state.coupons.map(c=>{const s=c.status==='issued'&&Date.parse(c.expiresAt)<Date.now()?'expired':c.status;return `<article class="coupon"><div><h3>${esc(c.title)}</h3><p>Canjeado ${date(c.issuedAt)} · Vence ${date(c.expiresAt)}</p><code>${esc(c.code)}</code></div><div>${status(s)}${s==='issued'?`<button class="btn ghost" data-copy="${esc(c.code)}">${icon('copy')} Copiar</button>`:''}</div></article>`;}).join(''):empty('Aún no tienes cupones. Completa retos y descubre las recompensas.','ticket')}`;}
function progressPage(){return `${heading('Cada detalle cuenta una historia','Tu experiencia se queda contigo. Tu próxima sorpresa también.')}<div class="columns"><div><section class="panel"><h2>Tu camino en el club</h2>${state.levels.map((l,i)=>`<div class="rank-row"><span class="rank-number">${icon(state.user.xp>=l.min?'check':'trophy')}</span><div><strong>${esc(l.name)}</strong><p class="small muted" style="margin:5px 0">Desde ${l.min} XP acumulados</p></div>${state.user.xp>=l.min?'<span class="xp-tag">Alcanzado</span>':''}</div>`).join('')}</section><section class="panel"><h2>Así va el club este mes</h2><p class="small muted">Experiencia ganada durante el mes UTC actual. Los alias protegen la identidad de los participantes.${state.user.isDemo?' Solo perfiles de demostración.':''}</p>${state.leaderboard.map((u,i)=>`<div class="rank-row"><span class="rank-number">${i+1}</span><div class="avatar">${icon('heart')}</div><strong>${esc(u.alias)}</strong><span class="xp-tag">${u.xp} XP</span></div>`).join('')}</section>${activity()}</div><aside>${levelPanel()}<section class="panel"><h3>Tu perfil de participación</h3><p class="small muted">${roleName(state.user.role)}. Al registrar tres compras verificadas te conviertes en embajador.</p><p class="small muted">Todos los clientes pueden participar en los retos y canjear recompensas. El nivel depende de tu experiencia acumulada.</p></section><section class="panel"><h3>Controla tus datos</h3><p class="small muted">Puedes retirar tu consentimiento y eliminar tu cuenta y registros del club.</p><button class="btn ghost" data-action="delete-account">Eliminar mi cuenta</button></section></aside></div>`;}
function chart(m){const max=Math.max(1,...m.series.map(s=>s.count));return `<div class="chart" role="img" aria-label="Interacciones registradas por día: ${m.series.map(s=>s.day+': '+s.count).join('; ')}">${m.series.map((s,i)=>`<div class="chart-col"><b>${s.count||''}</b><span style="height:${Math.max(2,s.count/max*125)}px"></span><label>${m.days===30&&i%5!==0?'':s.day.slice(8)+'/'+s.day.slice(5,7)}</label></div>`).join('')}</div>`;}
function metricsStats(m){return `<div class="stats">${stat('Clientes activos',m.activeUsers,`${m.totalUsers} clientes con consentimiento`,'users')}${stat('Conversión de cupones',m.conversion+'<small>%</small>',`${m.couponsUsed} utilizados / ${m.couponsIssued} emitidos`,'ticket')}${stat('Interacciones por cliente',m.weeklyFrequency,`${m.interactions} eventos / ${m.activeUsers} activos`,'chart')}${stat('Solicitudes anticipadas',m.reservations,`${m.confirmed} confirmadas · mínimo 48 h`,'calendar')}</div>`;}
function adminHome(){const m=metricData;return `${heading('Cada sorpresa, bajo control.','Una mirada al club y a los momentos que vienen.','<button class="btn secondary" data-action="refresh">'+icon('clock')+' Actualizar</button>')}<div class="notice">${includeDemo?'Viendo datos de demostración junto a los registros reales.':`Indicadores de los últimos ${m.days} días. Los perfiles de demostración se excluyen por defecto.`} Las cifras provienen de los eventos guardados; no son resultados simulados.</div>${metricsStats(m)}<div class="columns"><div><section class="panel"><div class="section-title"><h2>El pulso del club</h2><span class="tiny muted">ÚLTIMOS ${m.days} DÍAS</span></div>${chart(m)}</section><section class="panel"><div class="section-title"><h2>Próximas sorpresas</h2><button data-page="manage">Gestionar ${icon('arrow')}</button></div>${ordersTable(true)}</section></div><aside><section class="panel"><div class="level-medallion">${icon('heart')}</div><h2 style="text-align:center">Cada cliente importa.</h2><p class="small muted">Valida compras reales, confirma solicitudes y acompaña cada canje desde un solo lugar.</p><button class="btn full" data-page="manage">Ir a operación ${icon('arrow')}</button></section><section class="panel"><h3>Estado del piloto real</h3><p class="small muted">${m.pilot.participants}/10 participantes activos<br>${m.pilot.consecutiveDays}/5 días consecutivos con actividad</p>${status(m.pilot.ready?'confirmed':'pending')}<button class="btn ghost" data-page="pilot">Ver indicadores ${icon('arrow')}</button></section></aside></div>`;}
function management(){return `${heading('Detrás de cada momento especial','Confirma reservas, verifica compras y haz efectivas las recompensas.')}<div class="tabs">${[['reservations','Reservas'],['codes','Códigos de compra'],['coupons','Validar cupones'],['photos','Fotos compartidas']].map(([id,n])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${n}</button>`).join('')}</div>${tab==='reservations'?`<section class="panel">${ordersTable(true)}</section>`:tab==='codes'?`<div class="section-title"><h2>Compras verificadas</h2><button class="btn" data-action="new-code">+ Emitir código</button></div><div class="notice">Emite un código solo después de comprobar una compra real. La referencia es única y el código solo puede registrarlo el cliente seleccionado.</div><section class="panel">${state.codes.length?`<div class="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>CLIENTE</th><th>REFERENCIA</th><th>ESTADO</th></tr></thead><tbody>${state.codes.map(c=>`<tr><td><code>${esc(c.code)}</code><button data-copy="${esc(c.code)}" aria-label="Copiar código">${icon('copy')}</button></td><td>${esc(c.customer)}</td><td>${esc(c.reference)}</td><td>${status(c.usedAt?'used':'issued')}</td></tr>`).join('')}</tbody></table></div>`:empty('Emite el primer código cuando compruebes una compra.','code')}</section>`:tab==='coupons'?`<section class="panel" style="max-width:650px"><h2>Un beneficio, una sonrisa</h2><p class="small muted">Introduce el código que presenta el cliente. Al validarlo se marcará como utilizado de forma definitiva.</p><form id="validate-coupon"><div class="field"><label for="coupon-code">Código del cupón</label><input id="coupon-code" name="code" required placeholder="MFG-XXXXXXXX" maxlength="30"></div><p class="modal-error" role="alert"></p><button class="btn">Validar y aplicar beneficio ${icon('check')}</button></form></section><section class="panel"><h2>Cupones emitidos</h2>${state.coupons.length?state.coupons.map(c=>`<div class="activity-row"><div><strong>${esc(c.title)}</strong><small>${esc(c.code)} · Vence ${date(c.expiresAt)}</small></div><span style="margin-left:auto">${status(c.status==='issued'&&Date.parse(c.expiresAt)<Date.now()?'expired':c.status)}</span></div>`).join(''):empty('Todavía no hay cupones emitidos.','ticket')}</section>`:`<section class="panel"><h2>Fotos pendientes de revisión</h2><p class="small muted">Comprueba la imagen y su autorización antes de aprobar puntos. Los enlaces se abren en una nueva pestaña.</p>${state.contributions.length?state.contributions.map(c=>`<div class="activity-row"><div><a href="${esc(c.url)}" rel="noopener noreferrer" target="_blank">Ver imagen compartida ↗</a><small>${date(c.createdAt,true)} · ${statusName(c.status)}</small></div>${c.status==='pending'?`<div class="inline-actions" style="margin-left:auto"><button class="btn" data-photo="${c.id}" data-status="approved">Aprobar</button><button class="btn secondary" data-photo="${c.id}" data-status="rejected">Rechazar</button></div>`:''}</div>`).join(''):empty('No hay fotos para revisar.','camera')}</section>`}`;}
function usersPage(){return `${heading('Las personas detrás de los detalles','Clientes registrados y su participación en el club.')}<section class="panel"><div class="field"><label for="user-search">Buscar por nombre o correo</label><input id="user-search" placeholder="Escribe para filtrar…" type="search"></div><div class="table-scroll"><table><thead><tr><th>CLIENTE</th><th>PERFIL</th><th>EXPERIENCIA</th><th>SALDO</th><th>REGISTRO</th></tr></thead><tbody id="users-body">${state.users.filter(u=>u.role!=='admin').map(u=>`<tr data-search="${esc((u.name+' '+u.email).toLowerCase())}"><td><strong>${esc(u.name)}</strong><small>${esc(u.email)} ${u.isDemo?'· DEMO':''}</small></td><td>${roleName(u.role)}</td><td>${u.xp} XP<small>${esc(u.level.name)}</small></td><td>${u.balance} pts</td><td>${date(u.createdAt)}<small>Consentimiento registrado</small></td></tr>`).join('')}</tbody></table></div></section>`;}
function pilotPage(){const m=metricData;return `${heading('Decisiones con datos, detalles con sentido','Monitorea el piloto y exporta actividad sin datos de contacto.','<a class="btn secondary" href="/api/export">'+icon('download')+' Exportar CSV</a>')}<div class="panel"><div class="form-grid"><div class="field"><label for="metric-days">Ventana de medición</label><select id="metric-days"><option value="7" ${metricDays===7?'selected':''}>Últimos 7 días</option><option value="30" ${metricDays===30?'selected':''}>Últimos 30 días</option></select></div><label class="check" style="align-self:center"><input id="metric-demo" type="checkbox" ${includeDemo?'checked':''}><span>Incluir cuentas de demostración en los indicadores</span></label></div><p class="small muted" style="margin:0">${includeDemo?'Vista de comprobación: contiene datos de demostración. No debe presentarse como resultado de clientes reales.':'Vista del piloto real: solo clientes con consentimiento y sin marca de demostración.'}</p></div>${metricsStats(m)}<div class="grid-2"><section class="panel"><h2>Conversión de cupones</h2><p class="small muted">Cupones utilizados ÷ cupones emitidos × 100.</p><p class="small muted">Se toma la cohorte de cupones emitidos en la ventana seleccionada y se consulta cuántos han sido utilizados al momento de medir. Sin cupones emitidos se muestra 0%, sin inferir conversión.</p><div class="stat-value">${m.couponsUsed} / ${m.couponsIssued} × 100 = ${m.conversion}%</div></section><section class="panel"><h2>Frecuencia de interacción</h2><p class="small muted">Eventos de participación ÷ clientes activos en la ventana.</p><p class="small muted">Incluye reservas, trivia, compras verificadas, invitaciones verificadas, fotos y canjes. Excluye inicios de sesión, recargas, navegación y actividad del administrador. La ventana de 7 días corresponde al indicador semanal.</p><div class="stat-value">${m.interactions} / ${m.activeUsers} = ${m.weeklyFrequency}</div></section></div><section class="panel"><h2>Actividad observada</h2>${chart(m)}</section><section class="panel"><h2>Seguimiento del piloto real</h2><div class="notice ${m.pilot.ready?'success':''}">${m.pilot.ready?'Se alcanzó el mínimo de participación y continuidad observada. Falta la valoración del cliente para cerrar el piloto.':'Piloto pendiente: se requieren al menos 10 clientes reales activos y 5 días consecutivos con actividad registrada.'}</div><p class="small muted">${m.pilot.participants} participantes activos · ${m.pilot.consecutiveDays} días consecutivos. El seguimiento del piloto excluye siempre las cuentas de demostración. Las fechas se agrupan en horario de Bogotá. Esta comprobación mide actividad registrada y no acredita por sí sola reuniones, autorizaciones ni satisfacción.</p><p class="small muted">El CSV excluye siempre cuentas de demostración e identifica a cada participante con un seudónimo; no exporta nombres, correos, mensajes, códigos ni enlaces de fotografías.</p></section>`;}
function pageContent(admin){if(page==='home')return admin?adminHome():home();if(page==='create')return createPage();if(page==='rewards')return rewardsPage(admin);if(page==='challenges')return challengesPage(admin);if(page==='progress')return progressPage();if(page==='orders')return `${heading('Tus próximas historias','El estado de cada sorpresa, desde la primera idea.', '<button class="btn" data-page="create">+ Crear sorpresa</button>')}<section class="panel">${ordersTable(false)}</section>`;if(page==='coupons')return couponsPage();if(page==='manage')return management();if(page==='users')return usersPage();if(page==='pilot')return pilotPage();return '';}
function reservationModal(product,size='large'){
 const event=SHOWCASE_CATALOG.serviceFor(product)==='event';const min=new Date(Date.now()+49*3600000);const value=new Date(min.getTime()-min.getTimezoneOffset()*60000).toISOString().slice(0,16);
 modal(event?'Diseñemos tu celebración':'Hagamos algo inolvidable',`<form id="reservation-form"><input type="hidden" name="product" value="${esc(product)}"><input type="hidden" name="requestId" value="${crypto.randomUUID()}"><div class="notice">${esc(product)} · Solicitud sin cobro. Al guardarla podrás enviar el resumen al WhatsApp de pedidos.</div>${serviceConfigurationFields(product,size)}<div class="form-grid"><div class="field"><label for="recipient">${event?'Persona de contacto / homenajeado':'¿Para quién es?'}</label><input id="recipient" name="recipient" required minlength="2" maxlength="80" placeholder="Nombre de esa persona"></div><div class="field"><label for="occasion">La ocasión</label><select id="occasion" name="occasion"><option>Cumpleaños</option><option>Aniversario</option><option>Graduación</option><option>Solo porque sí</option><option>Evento empresarial</option><option>Otra ocasión</option></select></div></div><div class="form-grid"><div class="field"><label for="delivery">${event?'Fecha y hora del evento':'Fecha y hora de entrega'}</label><input id="delivery" name="delivery" type="datetime-local" required min="${value}" value="${value}"><small>Hora de tu dispositivo; el resumen muestra la hora de Colombia. Mínimo 48 horas.</small></div><div class="field"><label for="color">Tu paleta favorita</label><select id="color" name="color"><option>Rosa</option><option>Lavanda</option><option>Durazno</option><option>Personalizada</option></select></div></div><div class="form-grid"><div class="field"><label for="contact-phone">Tu celular de contacto</label><input id="contact-phone" name="contactPhone" type="tel" inputmode="tel" autocomplete="tel-national" required minlength="10" maxlength="20" placeholder="Ej. 300 123 4567"><small>Para coordinar tu pedido.</small></div><div class="field">${event?'<input type="hidden" name="deliveryMethod" value="delivery"><label>Servicio en el lugar del evento</label><p class="small muted">Coordinaremos el montaje contigo.</p>':'<label for="delivery-method">¿Cómo lo recibes?</label><select id="delivery-method" name="deliveryMethod"><option value="delivery">Domicilio</option><option value="pickup">Recogida con Milfiguras</option></select>'}</div></div><div class="field" id="delivery-address-field"><label for="delivery-address">${event?'Lugar del evento, dirección y ciudad':'Dirección, barrio y ciudad'}</label><input id="delivery-address" name="address" required minlength="8" maxlength="180" autocomplete="street-address" placeholder="Dirección completa, barrio y ciudad"><small>La cobertura y el costo se confirman con el equipo.</small></div><div class="field"><label for="gift-details">Regalo, presentación o decoración <span class="muted">(opcional)</span></label><textarea id="gift-details" name="giftDetails" maxlength="240" placeholder="Temática, colores personalizados, detalles del regalo…"></textarea></div><div class="field"><label for="message">${event?'Observaciones para tu celebración':'Una nota de tu corazón'}</label><textarea id="message" name="message" required minlength="2" maxlength="280" placeholder="Cuéntanos ese detalle especial…"></textarea><small>Hasta 280 caracteres. El precio final se acuerda antes de pagar.</small></div><p class="modal-error" role="alert"></p><button type="submit" class="btn full">Guardar pedido y ver resumen ${icon('heart')}</button></form>`);$('#modal').classList.add('configuration-dialog');updateBreakfastConfiguration($('#reservation-form'));
}
function rewardModal(id){const r=state.rewards.find(r=>r.id===id)||{title:'',description:'',cost:150,stock:10,active:true};modal(id?'Editar recompensa':'Nueva recompensa',`<form id="reward-form"><input name="id" type="hidden" value="${esc(id||'')}"><div class="field"><label for="title">Nombre</label><input id="title" name="title" required minlength="3" maxlength="90" value="${esc(r.title)}"></div><div class="field"><label for="description">Descripción y condiciones</label><textarea id="description" name="description" required minlength="5" maxlength="220">${esc(r.description)}</textarea></div><div class="form-grid"><div class="field"><label for="cost">Costo en puntos</label><input id="cost" name="cost" type="number" min="1" max="5000" required value="${r.cost}"></div><div class="field"><label for="stock">Existencias</label><input id="stock" name="stock" type="number" min="0" max="10000" required value="${r.stock}"></div></div><label class="check"><input name="active" type="checkbox" ${r.active?'checked':''}> Recompensa activa</label><p class="modal-error" role="alert"></p><button class="btn full">Guardar recompensa</button></form>`);}
function challengeModal(id){const c=state.challenges.find(c=>c.id===id);modal('Editar reto',`<form id="challenge-form"><input name="id" type="hidden" value="${esc(id)}"><div class="field"><label for="title">Nombre del reto</label><input id="title" name="title" required minlength="3" maxlength="90" value="${esc(c.title)}"></div><div class="field"><label for="description">Instrucciones</label><textarea id="description" name="description" required minlength="5" maxlength="240">${esc(c.description)}</textarea></div><div class="field"><label for="points">Puntos por acción (1 a 500)</label><input id="points" name="points" type="number" min="1" max="500" value="${c.points}" required></div><label class="check"><input name="active" type="checkbox" ${c.active?'checked':''}> Reto activo</label><div class="notice">Los cambios aplican a nuevas acciones. Las reservas pendientes conservan los puntos ofrecidos al solicitarlas.</div><p class="modal-error" role="alert"></p><button class="btn full">Guardar reglas</button></form>`);}
function privacy(){modal('Tus datos, con cuidado.',`<div class="privacy-copy"><p>Milfiguras BGA utiliza tu nombre, correo, celular, datos de entrega, solicitudes y actividad para operar el Club de Sorpresas. No pedimos datos de pago ni procesamos cobros.</p><h3>Participación voluntaria</h3><p>Al registrarte autorizas el tratamiento para estas finalidades. El piloto analiza actividad mediante seudónimos y excluye cuentas de demostración. El equipo administrador puede ver los datos necesarios para gestionar tus solicitudes.</p><h3>Control de tu información</h3><p>Desde Mi progreso puedes eliminar tu cuenta y sus registros de participación. Para consultas de acceso, corrección o tratamiento, contacta al equipo en <a href="https://www.instagram.com/milfiguras_bga/" target="_blank" rel="noopener noreferrer">@milfiguras_bga</a>.</p><h3>Pedidos por WhatsApp</h3><p>Si eliges abrir el resumen en WhatsApp, se compartirán los datos de ese pedido con el equipo de pedidos de Milfiguras en el número 3044817781. Puedes revisar el mensaje antes de enviarlo. La aplicación no envía mensajes automáticamente ni confirma su recepción.</p><h3>Imágenes y terceros</h3><p>Compartir una foto es opcional. Envía solo material propio o autorizado. El enlace se revisa manualmente; no se publica en el club. Cualquier publicación comercial adicional requiere autorización específica.</p><h3>Reglas transparentes</h3><p>Tu experiencia acumulada determina el nivel. Los canjes descuentan el saldo disponible y reservan existencias. Los cupones son personales, de un uso y vencen en 30 días. No se convierten en dinero. El envío gratuito aplica al área urbana de Bucaramanga; los beneficios se coordinan con Milfiguras.</p><p>Las reservas requieren al menos 48 horas de anticipación y confirmación de disponibilidad y precio. Los puntos se acreditan al confirmar la reserva. Tres compras verificadas habilitan el perfil embajador. Las trivias tienen un intento diario; las invitaciones dan 60 XP tras la primera compra verificada.</p></div>`);}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;const d=target.dataset;
 if(d.page){setNavigationOpen(false);page=d.page;try{await refresh();window.scrollTo({top:0,behavior:'instant'});}catch(error){toast(error.message,true);}return;}
 if(d.tab){tab=d.tab;render();return;}
 if(d.copy){try{await navigator.clipboard.writeText(d.copy);toast('Código copiado.');}catch{toast('Tu código: '+d.copy);}return;}
 if(d.product){reservationModal(d.product,d.size);return;}
 if(d.editReward){rewardModal(d.editReward);return;}if(d.editChallenge){challengeModal(d.editChallenge);return;}
 if(d.challenge==='reservation'){page='create';render();return;}
 if(d.challenge==='purchase'){modal('Tu sorpresa suma.',`<form id="purchase-form"><p class="small muted">Pide al equipo el código de tu compra verificada. Es personal y solo puedes utilizarlo una vez.</p><div class="field"><label for="purchase-code">Código de compra</label><input id="purchase-code" name="code" required maxlength="30" placeholder="COMPRA-XXXXXXXX"></div><p class="modal-error" role="alert"></p><button class="btn full">Registrar mi compra ${icon('star')}</button></form>`);return;}
 if(d.challenge==='trivia'){modal('El detalle de hoy',`<form id="trivia-form"><p>¿Con cuánta anticipación debes reservar tu sorpresa para que podamos cuidar cada detalle?</p><div class="options">${['El mismo día','Al menos 48 horas antes','Solo 12 horas antes'].map((a,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" required>${a}</label>`).join('')}</div><p class="small muted">Un intento al día, en horario de Bogotá. Los puntos se suman si respondes correctamente.</p><p class="modal-error" role="alert"></p><button class="btn full">Enviar respuesta ${icon('spark')}</button></form>`);return;}
 if(d.challenge==='photo'){modal('Comparte una sonrisa',`<form id="photo-form"><p class="small muted">Envía el enlace HTTPS de una foto de tu sorpresa. El equipo comprobará la imagen antes de asignar los puntos.</p><div class="field"><label for="photo-url">Enlace de la fotografía</label><input id="photo-url" name="url" type="url" pattern="https://.*" required maxlength="500" placeholder="https://…"></div><label class="check"><input type="checkbox" name="authorization" required>Confirmo que soy titular de la imagen o tengo autorización escrita de las personas que aparecen. Autorizo su revisión por Milfiguras para este reto.</label><p class="modal-error" role="alert"></p><button class="btn full">Enviar a revisión</button></form>`);return;}
 if(d.redeem){const r=state.rewards.find(r=>r.id===d.redeem);modal('Un premio con mucho cariño',`<p>Vas a canjear <strong>${esc(r.title)}</strong> por <strong>${r.cost} puntos</strong>.</p><p class="small muted">${esc(r.description)} Tu saldo quedará en ${state.user.balance-r.cost} puntos. El cupón vence en 30 días.</p><form id="redeem-form"><input type="hidden" name="rewardId" value="${r.id}"><p class="modal-error" role="alert"></p><button class="btn full">Confirmar mi canje ${icon('gift')}</button></form>`);return;}
 if(d.order||d.photo){const action=d.order?'reservations':'contributions';modal(d.order?'Gestionar solicitud':'Revisar foto',`<p>${d.status==='confirmed'?'Al confirmar, se asignarán los puntos ofrecidos al cliente.':d.status==='cancelled'?'La solicitud quedará cancelada y no se asignarán puntos.':d.status==='approved'?'Confirma que revisaste la foto y su autorización. Se asignarán los puntos del reto.':'La foto quedará rechazada y no se asignarán puntos.'}</p><form id="admin-decision"><input type="hidden" name="endpoint" value="${action}"><input type="hidden" name="id" value="${d.order||d.photo}"><input type="hidden" name="status" value="${d.status}"><p class="modal-error" role="alert"></p><button class="btn full">Confirmar decisión</button></form>`);return;}
 if(d.action==='menu'){setNavigationOpen(!$('.sidebar')?.classList.contains('open'));return;}if(d.action==='close-menu'){setNavigationOpen(false,true);return;}if(d.action==='close-modal'){closeModal();return;}if(d.action==='privacy'){privacy();return;}if(d.action==='auth-switch'){register=!register;renderAuth();return;}if(d.action==='new-reward'){rewardModal();return;}
 if(d.action==='new-code'){modal('Verifica una compra real',`<form id="code-form"><div class="notice">Este código acredita una compra. Comprueba la referencia antes de emitirlo.</div><div class="field"><label for="code-user">Cliente titular</label><select id="code-user" name="userId" required><option value="">Selecciona un cliente</option>${state.users.filter(u=>u.role!=='admin').map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.email)}</option>`).join('')}</select></div><div class="field"><label for="reference">Referencia de la compra</label><input id="reference" name="reference" minlength="3" maxlength="80" required placeholder="Ej. PED-2026-001"></div><p class="modal-error" role="alert"></p><button class="btn full">Crear código de un solo uso</button></form>`);return;}
 if(d.action==='delete-account'){modal('Eliminar mi cuenta',`<form id="delete-form"><p class="small muted">Esta acción elimina tu perfil, saldo, reservas, cupones y actividad. No podrás recuperar tus puntos.</p><div class="field"><label for="delete-confirm">Escribe ELIMINAR para confirmar</label><input id="delete-confirm" name="confirm" required pattern="ELIMINAR" autocomplete="off"></div><p class="modal-error" role="alert"></p><button class="btn danger full">Eliminar mis datos y cerrar sesión</button></form>`);return;}
 if(d.action==='logout'){try{await api('logout',{});state=null;register=false;renderAuth();}catch(err){toast(err.message,true);}return;}
 if(d.action==='refresh'){try{await refresh();toast('Datos actualizados.');}catch(err){toast(err.message,true);}}
});
document.addEventListener('submit',async e=>{const form=e.target;const formId=form.getAttribute('id');if(['profile-form','password-form'].includes(formId))return;e.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button[type="submit"],button.btn');if(button)button.disabled=true;try{const data=Object.fromEntries(new FormData(form));
 if(formId==='auth-form'){data.consent=form.elements.consent?.checked;await api(register?'register':'login',data);page='home';await refresh();if(pendingService){const selected=pendingService;pendingService=null;chooseService(selected.product,selected.size);}return;}
 const routes={'reservation-form':'reservations','purchase-form':'purchase','trivia-form':'trivia','redeem-form':'redeem','photo-form':'contributions','reward-form':'admin/rewards','challenge-form':'admin/challenges','code-form':'admin/codes','validate-coupon':'admin/coupons','delete-form':'account/delete'};
 if(formId==='reservation-form'){data.delivery=new Date(data.delivery).toISOString();collectServiceOptions(data);}if(formId==='trivia-form')data.answer=Number(data.answer);if(formId==='photo-form')data.authorization=form.elements.authorization.checked;if(formId==='reward-form'){data.cost=Number(data.cost);data.stock=Number(data.stock);data.active=form.elements.active.checked;}if(formId==='challenge-form'){data.points=Number(data.points);data.active=form.elements.active.checked;}
 const route=formId==='admin-decision'?'admin/'+data.endpoint:routes[formId];if(!route)throw new Error('No se reconoce esta acción. Recarga la página e inténtalo de nuevo.');const result=await api(route,data);closeModal();if(formId==='delete-form'){state=null;register=false;renderAuth();toast(result.message);return;}if(formId==='reservation-form')page='orders';if(formId==='redeem-form')page='coupons';await refresh();if(formId==='reservation-form'&&result.reservation)orderSummaryModal(result.reservation);toast(result.code?result.message+' '+result.code.code:result.message);if(result.points>0||formId==='redeem-form')celebrate();
 }catch(error){formError(form,error);}finally{busy=false;if(button)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='user-search'){const q=e.target.value.trim().toLowerCase();document.querySelectorAll('#users-body tr').forEach(row=>row.hidden=!row.dataset.search.includes(q));}});
document.addEventListener('change',async e=>{if(!['metric-days','metric-demo'].includes(e.target.id))return;if(e.target.id==='metric-days')metricDays=Number(e.target.value);else includeDemo=e.target.checked;try{await refresh();}catch(err){toast(err.message,true);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
(async()=>{try{await refresh();}catch{state=null;renderAuth();}})();

async function syncVisibleState(){if(!state||busy||document.hidden||$('#modal').open||$('.sidebar')?.classList.contains('open')||$('#profile-dropdown')&&!$('#profile-dropdown').hidden)return;try{await refresh();}catch(error){if(state)toast('No pudimos actualizar los datos. Revisa tu conexión.',true);}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncVisibleState();});
setInterval(syncVisibleState,30000);

// Drawer state is separate from page state so navigation never squeezes mobile content.
function setNavigationOpen(open,restoreFocus=false){
 const sidebar=$('.sidebar'),trigger=$('[data-action="menu"]'),backdrop=$('.navigation-backdrop');if(!sidebar)return;
 const mobile=matchMedia('(max-width: 1024px)').matches;open=Boolean(open&&mobile);
 sidebar.classList.toggle('open',open);document.body.classList.toggle('navigation-open',open);
 if(trigger){trigger.setAttribute('aria-expanded',String(open));trigger.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');}
 if(backdrop)backdrop.hidden=!open;
 sidebar.inert=mobile&&!open;
 if(open)sidebar.querySelector('.sidebar-close')?.focus({preventScroll:true});else if(restoreFocus)trigger?.focus({preventScroll:true});
}
function prepareResponsiveTables(){
 document.querySelectorAll('.reservations-table').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent);table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,i)=>cell.dataset.label=labels[i]||''));});
}
document.addEventListener('keydown',event=>{
 const sidebar=$('.sidebar');if(!sidebar?.classList.contains('open'))return;
 if(event.key==='Escape'){event.preventDefault();setNavigationOpen(false,true);return;}
 if(event.key==='Tab'){
  const controls=[...sidebar.querySelectorAll('button:not([disabled]),a[href]')].filter(el=>!el.hidden);const first=controls[0],last=controls.at(-1);
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
 }
});
window.addEventListener('resize',()=>{if(!matchMedia('(max-width: 1024px)').matches)setNavigationOpen(false);else if(!$('.sidebar')?.classList.contains('open'))setNavigationOpen(false);});
